package nettrace

import (
	"context"
	"errors"
	"fmt"
	"net/netip"
	"sync"
	"syscall"
	"time"
)

// prober opens one probe connection per TTL. The system implementation lives
// in the platform files; the tests drive run with a fake.
type prober interface {
	// open returns a connection whose probes leave with the given TTL.
	open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error)
}

// probeConn sends one probe and waits for what answers it.
type probeConn interface {
	// send emits the probe and returns the time it left.
	send() (time.Time, error)
	// await waits for the answer until the given time. It returns errSilent
	// when nothing came back by then, and ctx.Err() when ctx ended first.
	await(ctx context.Context, until time.Time) (reply, error)
	close() error
}

// errSilent is await's answer when nothing came back before its deadline.
var errSilent = errors.New("no answer before the probe timeout")

// probeResult is what one TTL's goroutine hands back. resolved is false when
// the probe was cut short (cancellation, deadline, upper TTL no longer needed).
type probeResult struct {
	ttl      int
	hop      Hop
	resolved bool
}

// run traces the path with p. Every connection is opened first, in the
// caller's goroutine, so that a failing open stops everything before any
// probe is sent; then one goroutine per TTL sends and awaits in parallel.
func run(ctx context.Context, target netip.Addr, opts Options, p prober) (Result, error) {
	opts = opts.Normalized()
	start := time.Now()
	runCtx, cancel := context.WithTimeout(ctx, opts.Deadline)
	defer cancel()

	conns, err := openAll(runCtx, p, target, opts.MaxHops)
	if err != nil {
		if runCtx.Err() != nil {
			return endedEarly(runCtx, target, nil, opts.MaxHops, start), nil
		}
		return Result{}, openError(err)
	}
	return probeAll(runCtx, target, opts, conns, start), nil
}

// openAll opens one connection per TTL, 1 to n. On failure it closes the ones
// already open and returns the error.
func openAll(ctx context.Context, p prober, target netip.Addr, n int) ([]probeConn, error) {
	conns := make([]probeConn, 0, n)
	for ttl := 1; ttl <= n; ttl++ {
		if err := ctx.Err(); err != nil {
			closeAll(conns)
			return nil, err
		}
		c, err := p.open(ctx, target, ttl)
		if err != nil {
			closeAll(conns)
			return nil, err
		}
		conns = append(conns, c)
	}
	return conns, nil
}

func closeAll(conns []probeConn) {
	for _, c := range conns {
		_ = c.close()
	}
}

// openError turns a refused socket option (ENOPROTOOPT, EOPNOTSUPP) into
// ErrUnsupported, keeping the raw error for the message. Anything else is
// returned as is: a refused connect() is not "unsupported", and the system
// prober wraps its own socket and setsockopt permission errors itself.
func openError(err error) error {
	for _, errno := range []error{syscall.ENOPROTOOPT, syscall.EOPNOTSUPP} {
		if errors.Is(err, errno) {
			return fmt.Errorf("%w: %w", ErrUnsupported, err)
		}
	}
	return err
}

// probeAll runs phase 2: one goroutine per connection.
func probeAll(ctx context.Context, target netip.Addr, opts Options, conns []probeConn, start time.Time) Result {
	n := len(conns)
	results := make(chan probeResult, n)
	cancels := make([]context.CancelFunc, n+1) // indexed by TTL
	var wg sync.WaitGroup
	for i, c := range conns {
		ttl := i + 1
		var tctx context.Context
		tctx, cancels[ttl] = context.WithCancel(ctx)
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() { _ = c.close() }()
			results <- probeOne(tctx, c, ttl, target, opts.ProbeTimeout)
		}()
	}

	t := newTally(n)
	cutAbove := func() {
		if term := t.terminal(); term > 0 {
			for ttl := term + 1; ttl <= n; ttl++ {
				cancels[ttl]()
			}
		}
	}
collect:
	for !t.complete() {
		select {
		case r := <-results:
			t.add(r)
			cutAbove()
		case <-ctx.Done():
			break collect
		}
	}
	for _, cancel := range cancels[1:] {
		cancel()
	}
	wg.Wait()
	close(results)
	for r := range results { // answers that landed while stopping
		t.add(r)
	}

	if t.complete() {
		return t.result(target, start)
	}
	return endedEarly(ctx, target, t, n, start)
}

// probeOne sends the probe for one TTL and turns what comes back into a Hop.
func probeOne(ctx context.Context, c probeConn, ttl int, target netip.Addr, timeout time.Duration) probeResult {
	sentAt, err := c.send()
	if err != nil {
		if ctx.Err() != nil {
			return probeResult{ttl: ttl}
		}
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rep, err := c.await(ctx, sentAt.Add(timeout))
	recvAt := time.Now()
	switch {
	case err != nil && ctx.Err() != nil:
		return probeResult{ttl: ttl}
	case errors.Is(err, errSilent):
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
	case err != nil:
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rtt := rep.RTT
	if rtt == 0 {
		rtt = recvAt.Sub(sentAt)
	}
	hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
	return probeResult{ttl: ttl, hop: hop, resolved: true}
}

// tally collects the resolved hops of a run.
type tally struct {
	hops []probeResult // indexed by TTL, index 0 unused
}

func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }

func (t *tally) add(r probeResult) {
	if r.resolved {
		t.hops[r.ttl] = r
	}
}

// terminal returns the smallest TTL that reached or was refused, or 0.
func (t *tally) terminal() int {
	for ttl := 1; ttl < len(t.hops); ttl++ {
		if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
			return ttl
		}
	}
	return 0
}

// complete reports whether the trace can end: every TTL up to the terminal
// one (or every TTL when there is none) is resolved.
func (t *tally) complete() bool {
	limit := len(t.hops) - 1
	if term := t.terminal(); term > 0 {
		limit = term
	}
	for ttl := 1; ttl <= limit; ttl++ {
		if !t.hops[ttl].resolved {
			return false
		}
	}
	return true
}

// result builds the Result of a complete tally.
func (t *tally) result(target netip.Addr, start time.Time) Result {
	last, outcome := len(t.hops)-1, OutcomeMaxHops
	if term := t.terminal(); term > 0 {
		last = term
		outcome = OutcomeReached
		if t.hops[term].hop.Kind == HopUnreachable {
			outcome = OutcomeUnreachable
		}
	}
	hops := make([]Hop, 0, last)
	for ttl := 1; ttl <= last; ttl++ {
		hops = append(hops, t.hops[ttl].hop)
	}
	return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
}

// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
// (n entries, index TTL-1), the resolved hops as they are and every other one
// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
	res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		res.Outcome = OutcomeDeadline
	}
	for ttl := 1; ttl <= n; ttl++ {
		if t != nil && t.hops[ttl].resolved {
			res.Hops = append(res.Hops, t.hops[ttl].hop)
		} else {
			res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
		}
	}
	return res
}
package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"time"
)

const (
	// MaxHopsLimit is the highest TTL a trace will probe.
	MaxHopsLimit = 30
	// DefaultProbeTimeout is how long one hop waits for an answer.
	DefaultProbeTimeout = 3 * time.Second
	// DeadlineLimit is the longest a whole trace may run.
	DeadlineLimit = 30 * time.Second
)

var (
	// ErrUnsupported is returned on platforms without a trace engine.
	ErrUnsupported = errors.New("path trace not supported on this platform")
	// ErrNotIPv4 is returned for a target that is not an IPv4 address.
	ErrNotIPv4 = errors.New("path trace supports IPv4 targets only")
	// ErrNotUnicast is returned for an unspecified, multicast or limited
	// broadcast target.
	ErrNotUnicast = errors.New("path trace needs a unicast target")
	// ErrNoRoute is returned when the system has no route to the target.
	ErrNoRoute = errors.New("no route to the target")
)

// Options tunes a trace. The zero value means "all defaults".
type Options struct {
	// MaxHops is the highest TTL probed, 1 to MaxHopsLimit.
	MaxHops int
	// ProbeTimeout is the wait for one hop's answer.
	ProbeTimeout time.Duration
	// Deadline bounds the whole trace.
	Deadline time.Duration
}

// Normalized returns the options with every out-of-range or unset value
// replaced by its default, and ProbeTimeout capped at Deadline.
func (o Options) Normalized() Options {
	if o.MaxHops <= 0 || o.MaxHops > MaxHopsLimit {
		o.MaxHops = MaxHopsLimit
	}
	if o.Deadline <= 0 || o.Deadline > DeadlineLimit {
		o.Deadline = DeadlineLimit
	}
	if o.ProbeTimeout <= 0 {
		o.ProbeTimeout = DefaultProbeTimeout
	}
	if o.ProbeTimeout > o.Deadline {
		o.ProbeTimeout = o.Deadline
	}
	return o
}

// HopKind says what a hop's probe got back.
type HopKind int

// The kinds of hop.
const (
	// HopSilent: no answer before the probe timeout.
	HopSilent HopKind = iota
	// HopRouter: an intermediate router answered (time exceeded).
	HopRouter
	// HopTarget: the target itself answered.
	HopTarget
	// HopUnreachable: a router reported the target as unreachable.
	HopUnreachable
	// HopUnresolved: an answer arrived but its sender could not be read.
	HopUnresolved
	// HopError: the probe could not be sent, or the answer was unexpected
	// (an error from the local stack, or a reply that is not ICMP).
	HopError
)

// String returns the kind's name.
func (k HopKind) String() string {
	switch k {
	case HopSilent:
		return "silent"
	case HopRouter:
		return "router"
	case HopTarget:
		return "target"
	case HopUnreachable:
		return "unreachable"
	case HopUnresolved:
		return "unresolved"
	case HopError:
		return "error"
	}
	return "unknown"
}

// Hop is the result of probing one TTL.
type Hop struct {
	TTL      int
	Kind     HopKind
	Addr     netip.Addr
	RTT      time.Duration
	ICMPType uint8
	ICMPCode uint8
	Err      error
}

// Outcome says why a trace ended.
type Outcome int

// The ways a trace ends. The zero value is OutcomeReached, so read an Outcome
// only when Trace returned no error.
const (
	// OutcomeReached: the target answered.
	OutcomeReached Outcome = iota
	// OutcomeMaxHops: MaxHops was exhausted without reaching the target.
	OutcomeMaxHops
	// OutcomeDeadline: the overall deadline expired.
	OutcomeDeadline
	// OutcomeCancelled: the caller's context was canceled.
	OutcomeCancelled
	// OutcomeUnreachable: a router reported the target as unreachable.
	OutcomeUnreachable
)

// String returns the outcome in US English.
func (o Outcome) String() string {
	switch o {
	case OutcomeReached:
		return "reached"
	case OutcomeMaxHops:
		return "max hops"
	case OutcomeDeadline:
		return "deadline"
	case OutcomeCancelled:
		return "canceled"
	case OutcomeUnreachable:
		return "unreachable"
	}
	return "unknown"
}

// Result is a finished trace.
//
// Hops is cut at the terminal hop (target reached or refused) or, when the
// trace ends at MaxHops, holds one hop per TTL. When a cancellation or the
// deadline ends it first, Hops holds exactly MaxHops entries, Hops[i].TTL ==
// i+1, and every probe that did not resolve is a HopUnresolved; so even with a
// terminal hop already known, the TTLs above it can show up as HopUnresolved.
// The probes above the target are all sent: only their wait is cut short.
//
// Always check the error Trace returned before
// reading it: the zero Result (and so the zero Outcome, OutcomeReached) means
// "no trace", never "reached".
type Result struct {
	Target   netip.Addr
	Outcome  Outcome
	Hops     []Hop
	Duration time.Duration
}

// Supported reports whether this platform can trace: nil, or ErrUnsupported.
func Supported() error {
	return supported()
}

// Trace probes the path to target. An IPv4-mapped IPv6 target is converted to
// IPv4; any other non-IPv4 target gets ErrNotIPv4 and nothing is sent. An
// unspecified (0.0.0.0), multicast or limited broadcast (255.255.255.255)
// target gets ErrNotUnicast. Subnet broadcasts cannot be told apart and are not
// checked. Loopback and private addresses are allowed: whether tracing them is
// acceptable is the caller's decision, at its own boundary.
//
// The errors Trace returns and Hop.Err carry raw platform text (errno
// messages): match the sentinels with errors.Is and show fixed labels, never
// that text in a summary.
func Trace(ctx context.Context, target netip.Addr, opts Options) (Result, error) {
	if err := supported(); err != nil {
		return Result{}, err
	}
	target = target.Unmap()
	if !target.Is4() {
		return Result{}, ErrNotIPv4
	}
	if target.IsUnspecified() || target.IsMulticast() || target == netip.AddrFrom4([4]byte{255, 255, 255, 255}) {
		return Result{}, ErrNotUnicast
	}
	return run(ctx, target, opts, systemProber())
}
