			return probeResult{ttl: ttl}
		}
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rep, err := c.await(ctx, sentAt.Add(timeout))
	recvAt := time.Now()
	switch {
	case err != nil && ctx.Err() != nil:
		return probeResult{ttl: ttl}
	case errors.Is(err, errSilent):
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopSilent}, resolved: true}
	case err != nil:
		return probeResult{ttl: ttl, hop: Hop{TTL: ttl, Kind: HopError, Err: err}, resolved: true}
	}
	rtt := rep.RTT
	if rtt == 0 {
		rtt = recvAt.Sub(sentAt)
	}
	hop := Hop{TTL: ttl, Kind: classify(rep, target), Addr: rep.Addr, RTT: rtt, ICMPType: rep.ICMPType, ICMPCode: rep.ICMPCode}
	return probeResult{ttl: ttl, hop: hop, resolved: true}
}

// tally collects the resolved hops of a run.
type tally struct {
	hops []probeResult // indexed by TTL, index 0 unused
}

func newTally(n int) *tally { return &tally{hops: make([]probeResult, n+1)} }

func (t *tally) add(r probeResult) {
	if r.resolved {
		t.hops[r.ttl] = r
	}
}

// terminal returns the smallest TTL that reached or was refused, or 0.
func (t *tally) terminal() int {
	for ttl := 1; ttl < len(t.hops); ttl++ {
		if r := t.hops[ttl]; r.resolved && (r.hop.Kind == HopTarget || r.hop.Kind == HopUnreachable) {
			return ttl
		}
	}
	return 0
}

// complete reports whether the trace can end: every TTL up to the terminal
// one (or every TTL when there is none) is resolved.
func (t *tally) complete() bool {
	limit := len(t.hops) - 1
	if term := t.terminal(); term > 0 {
		limit = term
	}
	for ttl := 1; ttl <= limit; ttl++ {
		if !t.hops[ttl].resolved {
			return false
		}
	}
	return true
}

// result builds the Result of a complete tally.
func (t *tally) result(target netip.Addr, start time.Time) Result {
	last, outcome := len(t.hops)-1, OutcomeMaxHops
	if term := t.terminal(); term > 0 {
		last = term
		outcome = OutcomeReached
		if t.hops[term].hop.Kind == HopUnreachable {
			outcome = OutcomeUnreachable
		}
	}
	hops := make([]Hop, 0, last)
	for ttl := 1; ttl <= last; ttl++ {
		hops = append(hops, t.hops[ttl].hop)
	}
	return Result{Target: target, Outcome: outcome, Hops: hops, Duration: time.Since(start)}
}

// endedEarly builds the Result of a run that ctx cut short: one entry per TTL
// (n entries, index TTL-1), the resolved hops as they are and every other one
// as HopUnresolved with its TTL. t is nil when nothing was probed yet.
func endedEarly(ctx context.Context, target netip.Addr, t *tally, n int, start time.Time) Result {
	res := Result{Target: target, Outcome: OutcomeCancelled, Hops: make([]Hop, 0, n), Duration: time.Since(start)}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		res.Outcome = OutcomeDeadline
	}
	for ttl := 1; ttl <= n; ttl++ {
		if t != nil && t.hops[ttl].resolved {
			res.Hops = append(res.Hops, t.hops[ttl].hop)
		} else {
			res.Hops = append(res.Hops, Hop{TTL: ttl, Kind: HopUnresolved})
		}
	}
	return res
}
package nettrace

import (
	"context"
	"errors"
	"net/netip"
	"time"
)

const (
	// MaxHopsLimit is the highest TTL a trace will probe.
	MaxHopsLimit = 30
	// DefaultProbeTimeout is how long one hop waits for an answer.
	DefaultProbeTimeout = 3 * time.Second
	// DeadlineLimit is the longest a whole trace may run.
	DeadlineLimit = 30 * time.Second
)

var (
	// ErrUnsupported is returned on platforms without a trace engine.
	ErrUnsupported = errors.New("path trace not supported on this platform")
	// ErrNotIPv4 is returned for a target that is not an IPv4 address.
	ErrNotIPv4 = errors.New("path trace supports IPv4 targets only")
	// ErrNotUnicast is returned for an unspecified, multicast or limited
	// broadcast target.
	ErrNotUnicast = errors.New("path trace needs a unicast target")
	// ErrNoRoute is returned when the system has no route to the target.
	ErrNoRoute = errors.New("no route to the target")
)

// Options tunes a trace. The zero value means "all defaults".
type Options struct {
	// MaxHops is the highest TTL probed, 1 to MaxHopsLimit.
	MaxHops int
	// ProbeTimeout is the wait for one hop's answer.
	ProbeTimeout time.Duration
	// Deadline bounds the whole trace.
	Deadline time.Duration
}

// Normalized returns the options with every out-of-range or unset value
// replaced by its default, and ProbeTimeout capped at Deadline.
func (o Options) Normalized() Options {
	if o.MaxHops <= 0 || o.MaxHops > MaxHopsLimit {
		o.MaxHops = MaxHopsLimit
	}
	if o.Deadline <= 0 || o.Deadline > DeadlineLimit {
		o.Deadline = DeadlineLimit
	}
	if o.ProbeTimeout <= 0 {
		o.ProbeTimeout = DefaultProbeTimeout
	}
	if o.ProbeTimeout > o.Deadline {
		o.ProbeTimeout = o.Deadline
	}
	return o
}

// HopKind says what a hop's probe got back.
type HopKind int

// The kinds of hop.
const (
	// HopSilent: no answer before the probe timeout.
	HopSilent HopKind = iota
	// HopRouter: an intermediate router answered (time exceeded).
	HopRouter
	// HopTarget: the target itself answered.
	HopTarget
	// HopUnreachable: a router reported the target as unreachable.
	HopUnreachable
	// HopUnresolved: an answer arrived but its sender could not be read.
	HopUnresolved
	// HopError: the probe could not be sent, or the answer was unexpected
	// (an error from the local stack, or a reply that is not ICMP).
	HopError
)

// String returns the kind's name.
func (k HopKind) String() string {
	switch k {
	case HopSilent:
		return "silent"
	case HopRouter:
		return "router"
	case HopTarget:
		return "target"
	case HopUnreachable:
		return "unreachable"
	case HopUnresolved:
		return "unresolved"
	case HopError:
		return "error"
	}
	return "unknown"
}

// Hop is the result of probing one TTL.
type Hop struct {
	TTL      int
	Kind     HopKind
	Addr     netip.Addr
	RTT      time.Duration
	ICMPType uint8
	ICMPCode uint8
	Err      error
}

// Outcome says why a trace ended.
type Outcome int

// The ways a trace ends. The zero value is OutcomeReached, so read an Outcome
// only when Trace returned no error.
const (
	// OutcomeReached: the target answered.
	OutcomeReached Outcome = iota
	// OutcomeMaxHops: MaxHops was exhausted without reaching the target.
	OutcomeMaxHops
	// OutcomeDeadline: the overall deadline expired.
	OutcomeDeadline
	// OutcomeCancelled: the caller's context was canceled.
	OutcomeCancelled
	// OutcomeUnreachable: a router reported the target as unreachable.
	OutcomeUnreachable
)

// String returns the outcome in US English.
func (o Outcome) String() string {
	switch o {
	case OutcomeReached:
		return "reached"
	case OutcomeMaxHops:
		return "max hops"
	case OutcomeDeadline:
		return "deadline"
	case OutcomeCancelled:
		return "canceled"
	case OutcomeUnreachable:
		return "unreachable"
	}
	return "unknown"
}

// Result is a finished trace.
//
// Hops is cut at the terminal hop (target reached or refused) or, when the
// trace ends at MaxHops, holds one hop per TTL. When a cancellation or the
// deadline ends it first, Hops holds exactly MaxHops entries, Hops[i].TTL ==
// i+1, and every probe that did not resolve is a HopUnresolved; so even with a
// terminal hop already known, the TTLs above it can show up as HopUnresolved.
// The probes above the target are all sent: only their wait is cut short.
//
// Always check the error Trace returned before
// reading it: the zero Result (and so the zero Outcome, OutcomeReached) means
// "no trace", never "reached".
type Result struct {
	Target   netip.Addr
	Outcome  Outcome
	Hops     []Hop
	Duration time.Duration
}

// Supported reports whether this platform can trace: nil, or ErrUnsupported.
func Supported() error {
	return supported()
}

// Trace probes the path to target. An IPv4-mapped IPv6 target is converted to
// IPv4; any other non-IPv4 target gets ErrNotIPv4 and nothing is sent. An
// unspecified (0.0.0.0), multicast or limited broadcast (255.255.255.255)
// target gets ErrNotUnicast. Subnet broadcasts cannot be told apart and are not
// checked. Loopback and private addresses are allowed: whether tracing them is
// acceptable is the caller's decision, at its own boundary.
//
// The errors Trace returns and Hop.Err carry raw platform text (errno
// messages): match the sentinels with errors.Is and show fixed labels, never
// that text in a summary.
func Trace(ctx context.Context, target netip.Addr, opts Options) (Result, error) {
	if err := supported(); err != nil {
		return Result{}, err
	}
	target = target.Unmap()
	if !target.Is4() {
		return Result{}, ErrNotIPv4
	}
	if target.IsUnspecified() || target.IsMulticast() || target == netip.AddrFrom4([4]byte{255, 255, 255, 255}) {
		return Result{}, ErrNotUnicast
	}
	return run(ctx, target, opts, systemProber())
}
package nettrace

import (
	"context"
	"errors"
	"fmt"
	"net/netip"
	"runtime"
	"sync"
	"sync/atomic"
	"syscall"
	"testing"
	"time"
)

// The engine tests run on every platform: they drive run() with a fake prober
// and real (short) time, never a socket.

var engineTarget = netip.MustParseAddr("192.0.2.99")

// probeSpec scripts what one TTL's connection does.
type probeSpec struct {
	openErr   error         // open fails with this error
	openBlock bool          // open blocks until ctx is done, then returns ctx.Err()
	sendErr   error         // send fails with this error
	sendDelay time.Duration // send takes this long
	delay     time.Duration // the answer arrives this long after the send
	rep       *reply        // the answer; with awaitErr nil too, the probe is silent
	awaitErr  error         // await fails with this error after delay
	// ignoreUntil models a probe that nothing but the trace's own deadline or
	// a cancellation can end: await does not honor its until argument.
	ignoreUntil bool
}

type fakeProber struct {
	spec func(ttl int) probeSpec
	n    int // MaxHops of the run: every open must succeed before any send

	attempts, openOK, closes, sends, awaits atomic.Int32

	onOpen, onSend, onAwait func(ttl int)
	// onReply runs just before await hands an answer back.
	onReply func(ttl int)

	// barrier: await blocks until barrierN probes are waiting at once.
	barrierN        int
	barrierCh       chan struct{}
	waiting         atomic.Int32
	barrierTimeouts atomic.Int32

	mu         sync.Mutex
	violations []string
}

func newFake(n int, spec func(ttl int) probeSpec) *fakeProber {
	return &fakeProber{spec: spec, n: n}
}

func (p *fakeProber) violate(format string, args ...any) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.violations = append(p.violations, fmt.Sprintf(format, args...))
}

func (p *fakeProber) withBarrier(n int) *fakeProber {
	p.barrierN = n
	p.barrierCh = make(chan struct{})
	return p
}

func (p *fakeProber) open(ctx context.Context, dst netip.Addr, ttl int) (probeConn, error) {
	p.attempts.Add(1)
	if dst != engineTarget {
		p.violate("open for %v, want %v", dst, engineTarget)
	}
	if p.onOpen != nil {
		p.onOpen(ttl)
	}
	s := p.spec(ttl)
	if s.openBlock {
		<-ctx.Done()
		return nil, ctx.Err()
	}
	if s.openErr != nil {
		return nil, s.openErr
	}
	p.openOK.Add(1)
	return &fakeConn{p: p, ttl: ttl, spec: s}, nil
}

type fakeConn struct {
	p      *fakeProber
	ttl    int
	spec   probeSpec
	sentAt time.Time
	closed atomic.Bool
}

func (c *fakeConn) send() (time.Time, error) {
	p := c.p
	p.sends.Add(1)
	if got := int(p.openOK.Load()); got != p.n {
		p.violate("TTL %d sent with only %d/%d connections open", c.ttl, got, p.n)
	}
	if p.onSend != nil {
		p.onSend(c.ttl)
	}
	if c.spec.sendDelay > 0 {
		time.Sleep(c.spec.sendDelay)
	}
	if c.spec.sendErr != nil {
		return time.Time{}, c.spec.sendErr
	}
	c.sentAt = time.Now()
	return c.sentAt, nil
}

func (c *fakeConn) await(ctx context.Context, until time.Time) (reply, error) {
	p := c.p
	p.awaits.Add(1)
	if p.onAwait != nil {
		p.onAwait(c.ttl)
	}
	if p.barrierCh != nil {
		if int(p.waiting.Add(1)) == p.barrierN {
			close(p.barrierCh)
		}
		select {
		case <-p.barrierCh:
		case <-ctx.Done():
			return reply{}, ctx.Err()
		case <-time.After(2 * time.Second):
			p.barrierTimeouts.Add(1)
			return reply{}, errors.New("fake: barrier timeout, probes are not in flight together")
		}
	}
	if err := ctx.Err(); err != nil {
		return reply{}, err
	}
	s := c.spec

content.content:
	s := c.spec
	answers := s.rep != nil || s.awaitErr != nil
	replyAt := c.sentAt.Add(s.delay)
	var fire time.Time
	silent := false
	switch {
	case !answers && s.ignoreUntil:
		<-ctx.Done()
		return reply{}, ctx.Err()
	case !answers || (!s.ignoreUntil && replyAt.After(until)):
		fire, silent = until, true
	default:
		fire = replyAt
	}
	t := time.NewTimer(time.Until(fire))
	defer t.Stop()
	select {
	case <-ctx.Done():
		return reply{}, ctx.Err()
	case <-t.C:
	}
	if silent {
		if err := ctx.Err(); err != nil {
			return reply{}, err
		}
		return reply{}, errSilent
	}
	if s.awaitErr != nil {
		return reply{}, s.awaitErr
	}
	if p.onReply != nil {
		p.onReply(c.ttl)
	}
	return *s.rep, nil
}

func (c *fakeConn) close() error {
	if c.closed.Swap(true) {
		c.p.violate("TTL %d closed twice", c.ttl)
	}
	c.p.closes.Add(1)
	return nil
}

// assertBalanced checks the invariants every run must keep, whatever happened.
func assertBalanced(t *testing.T, p *fakeProber) {
	t.Helper()
	if o, c := p.openOK.Load(), p.closes.Load(); o != c {
		t.Errorf("opened %d connections but closed %d", o, c)
	}
	p.mu.Lock()
	defer p.mu.Unlock()
	for _, v := range p.violations {
		t.Error(v)
	}
}

func routerReply(addr string) *reply {
	return &reply{Addr: netip.MustParseAddr(addr), ICMPType: icmpTimeExceeded, Origin: originICMP}
}

func targetReply() *reply {
	return &reply{Addr: engineTarget, ICMPType: icmpDestUnreachable, ICMPCode: icmpCodePortUnreach, Origin: originICMP}
}

func unreachReply(addr string, code uint8) *reply {
	return &reply{Addr: netip.MustParseAddr(addr), ICMPType: icmpDestUnreachable, ICMPCode: code, Origin: originICMP}
}

// table builds a spec function from per-TTL specs, with a default for the rest.
func table(def probeSpec, m map[int]probeSpec) func(int) probeSpec {
	return func(ttl int) probeSpec {
		if s, ok := m[ttl]; ok {
			return s
		}
		return def
	}
}

type runOut struct {
	res Result
	err error
}

// runBG starts run and returns a channel for its result.
func runBG(ctx context.Context, opts Options, p prober) <-chan runOut {
	ch := make(chan runOut, 1)
	go func() {
		res, err := run(ctx, engineTarget, opts, p)
		ch <- runOut{res, err}
	}()
	return ch
}

func waitRun(t *testing.T, ch <-chan runOut) runOut {
	t.Helper()
	select {
	case out := <-ch:
		return out
	case <-time.After(5 * time.Second):
		t.Fatal("run did not return within 5s")
		return runOut{}
	}
}

func mustRun(t *testing.T, ctx context.Context, opts Options, p prober) Result {
	t.Helper()
	res, err := run(ctx, engineTarget, opts, p)
	if err != nil {
		t.Fatalf("run: unexpected error %v", err)
	}
	if res.Target != engineTarget {
		t.Errorf("Result.Target = %v, want %v", res.Target, engineTarget)
	}
	return res
}

// Criterion 1: hops in order, address, RTT, list cut at the target.
func TestRunReachesTargetAndCutsTheList(t *testing.T) {
	silentForever := probeSpec{ignoreUntil: true}
	fp := newFake(8, table(silentForever, map[int]probeSpec{
		1: {rep: routerReply("10.0.0.1"), delay: 10 * time.Millisecond},
		2: {rep: routerReply("10.0.0.2"), delay: 20 * time.Millisecond},
		3: {rep: routerReply("10.0.0.3"), delay: 30 * time.Millisecond},
		4: {rep: targetReply(), delay: 40 * time.Millisecond},
		// TTL 5..8 never answer: they must be canceled, not waited for.
	}))
	start := time.Now()
	res := mustRun(t, context.Background(), Options{MaxHops: 8, ProbeTimeout: 5 * time.Second}, fp)
	elapsed := time.Since(start)

	if res.Outcome != OutcomeReached {
		t.Fatalf("Outcome = %v, want reached", res.Outcome)
	}
	if len(res.Hops) != 4 {
		t.Fatalf("len(Hops) = %d, want 4 (cut at the target): %+v", len(res.Hops), res.Hops)
	}
	want := []struct {
		kind  HopKind
		addr  string
		delay time.Duration
	}{
		{HopRouter, "10.0.0.1", 10 * time.Millisecond},
		{HopRouter, "10.0.0.2", 20 * time.Millisecond},
		{HopRouter, "10.0.0.3", 30 * time.Millisecond},
		{HopTarget, engineTarget.String(), 40 * time.Millisecond},
	}
	for i, w := range want {
		h := res.Hops[i]
		if h.TTL != i+1 {
			t.Errorf("Hops[%d].TTL = %d, want %d", i, h.TTL, i+1)
		}
		if h.Kind != w.kind {
			t.Errorf("Hops[%d].Kind = %v, want %v", i, h.Kind, w.kind)
		}
		if h.Addr != netip.MustParseAddr(w.addr) {
			t.Errorf("Hops[%d].Addr = %v, want %s", i, h.Addr, w.addr)
		}
		if h.RTT < w.delay || h.RTT > w.delay+200*time.Millisecond {
			t.Errorf("Hops[%d].RTT = %v, want within [%v, %v]", i, h.RTT, w.delay, w.delay+200*time.Millisecond)
		}
	}
	if elapsed > time.Second {
		t.Errorf("run took %v: the probes above the target were waited for", elapsed)
	}
	if res.Duration <= 0 || res.Duration > elapsed+50*time.Millisecond {
		t.Errorf("Duration = %v, want in (0, %v]", res.Duration, elapsed)
	}
	if got := fp.openOK.Load(); got != 8 {
		t.Errorf("opened %d connections, want 8 (one per TTL)", got)
	}
	assertBalanced(t, fp)
}

// An RTT the prober already filled in is kept as is.
func TestRunKeepsAnRTTTheProberFilledIn(t *testing.T) {
	r := targetReply()
	r.RTT = 7 * time.Millisecond
	fp := newFake(2, table(probeSpec{ignoreUntil: true}, map[int]probeSpec{
		1: {rep: r, delay: 20 * time.Millisecond},
	}))
	res := mustRun(t, context.Background(), Options{MaxHops: 2, ProbeTimeout: time.Second}, fp)
	if len(res.Hops) != 1 || res.Hops[0].RTT != 7*time.Millisecond {
		t.Fatalf("Hops = %+v, want one hop with RTT 7ms", res.Hops)
	}
	assertBalanced(t, fp)
}

