func TestRunCallbackCallsAreSequential(t *testing.T) {
	const n = 12
	fp := newFake(n, table(probeSpec{rep: routerReply("10.0.0.1"), delay: 10 * time.Millisecond}, nil)).withBarrier(n)
	rec := &hopRecorder{nap: 3 * time.Millisecond}
