		t.Fatalf("run: %v", err)
	}
	if res.Outcome != OutcomeMaxHops || len(res.Hops) != n {
		t.Fatalf("Outcome = %v, %d hops; want max hops, %d", res.Outcome, len(res.Hops), n)
	}
	rec.check(t)
