	defer cancel()
	rec := &hopRecorder{also: func(_ Hop, n int) {
		if n == 2 {
			cancel()
		}
	}}
	done := make(chan runOut, 1)
	go func() {
		res, err := run(ctx, engineTarget, Options{MaxHops: 5, ProbeTimeout: 10 * time.Second}, fp, rec.onHop)
		rec.finish()
		done <- runOut{res, err}
	}()
	out := waitRun(t, done)
	if out.err != nil {
		t.Fatalf("run: %v", out.err)
